function toast(msg,type=''){const el=$('toast');el.textContent=msg;el.className='toast show '+type;clearTimeout(el._t);el._t=setTimeout(()=>el.className='toast',3200)}
function fail(err,prefix=''){console.error(err);const msg=err?.message||err?.error_description||String(err||'Error');toast((prefix?prefix+': ':'')+friendlyError(msg),'bad')}
function friendlyError(msg){
  const m=String(msg||'');
  if(m.includes('QR_REQUIRED'))return'Debe escanear nuevamente el QR de la máquina.';
  if(m.includes('MISSING_ANSWERS'))return'Faltan puntos por responder.';
  if(m.includes('MISSING_OBSERVATIONS'))return'Falta explicar una falla o un N/A.';
  if(m.includes('MISSING_REQUIRED_PHOTOS'))return'Faltan fotografías obligatorias.';
  if(m.includes('MISSING_RANDOM_PHOTOS'))return'Faltan fotografías seleccionadas aleatoriamente.';
  if(m.includes('REVIEW_TOO_FAST')){const n=m.split(':').pop();return`La ronda todavía es demasiado rápida. Tiempo mínimo: ${n||30} segundos.`}
  if(m.includes('review_sessions_one_per_machine_shift'))return'Esta máquina ya tiene una ronda creada para este turno.';
  if(m.includes('duplicate key'))return'Ya existe un registro con ese código o nombre.';
  if(m.includes('Review identity'))return'No se puede cambiar la máquina, fecha, turno o molde de una ronda ya iniciada.';
  return m.replace(/^.*?message[:=]\s*/i,'');
}
async function must(p){const {data,error}=await p;if(error)throw error;return data}
