if(document.readyState==='loading')window.addEventListener('DOMContentLoaded',init);else init();
async function init(){
  if(!window.supabase){$('loginError').textContent='No se pudo cargar el cliente seguro. Revise la conexión a internet.';return}
  db=window.supabase.createClient(SUPABASE_URL,SUPABASE_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
  wireUI();
  $('workDate').value=today();
  const {data:{session}}=await db.auth.getSession();
  if(session){try{await enterSession(session)}catch(e){await db.auth.signOut();showLogin();fail(e)}}else showLogin();
  db.auth.onAuthStateChange((_event,session)=>{if(!session&&S.session)showLogin()});
}

