async function login(e){
  e.preventDefault();$('loginError').textContent='';
  const username=$('loginUser').value.trim().toLowerCase(),password=$('loginPass').value;
  if(!username||!password)return;
  try{
    const {data,error}=await db.auth.signInWithPassword({email:`${username}@controlintegral.calego.local`,password});
    if(error)throw error;await enterSession(data.session);
  }catch(err){$('loginError').textContent='Usuario o clave incorrectos.';console.error(err)}
}
async function enterSession(session){
  S.session=session;
  S.profile=await must(db.from('profiles').select('*').eq('id',session.user.id).single());
  if(!S.profile.active)throw new Error('Usuario inactivo');
  await loadConfig();
  $('loginScreen').classList.add('hidden');$('appShell').classList.remove('hidden');
  $('userChip').textContent=`${S.profile.full_name} · ${roleLabel(S.profile.role)}`;
  $('workDate').value=today();$('workDate').disabled=!isManager();
  renderRoleUI();
  showPage(isManager()?'dashboard':'checklist');
  setSync('Conectado a Control Integral Calego');
}
function showLogin(){S.session=null;S.profile=null;$('appShell').classList.add('hidden');$('loginScreen').classList.remove('hidden')}
async function logout(){stopQrScanner();await db.auth.signOut();location.reload()}
function setSync(text){$('syncState').textContent=text}

async function loadConfig(){
  setSync('Sincronizando…');
  const [areas,modules,machines,items,molds,moldParams,compat,settings,random]=await Promise.all([
    must(db.from('areas').select('*').order('sort_order')),
    must(db.from('modules').select('*').order('sort_order')),
    must(db.from('machines').select('id,module_id,code,name,active,sort_order,created_at,updated_at').order('sort_order')),
    must(db.from('checklist_items').select('*').order('sort_order')),
    must(db.from('molds').select('*').order('code')),
    must(db.from('mold_parameters').select('*').order('sort_order')),
    must(db.from('mold_machine_compatibility').select('*')),
    must(db.from('app_settings').select('*')),
    must(db.from('random_photo_settings').select('*').eq('id',true).maybeSingle())
  ]);
  S.areas=areas||[];S.modules=modules||[];S.machines=machines||[];S.items=items||[];S.molds=molds||[];S.moldParams=moldParams||[];S.compat=compat||[];
  const map=Object.fromEntries((settings||[]).map(x=>[x.key,x.value]));S.settings={qr_required:map.qr_required!==false,qr_unlock_minutes:Number(map.qr_unlock_minutes||10)};
  if(random)S.random={enabled:!!random.enabled,count:Number(random.count||4),scope:random.scope||'module'};
  if(isManager()){
    const [profiles,ap,mp]=await Promise.all([must(db.from('profiles').select('*').order('full_name')),must(db.from('user_area_permissions').select('*')),must(db.from('user_module_permissions').select('*'))]);
    S.profiles=profiles||[];S.allAreaPerms=ap||[];S.allModulePerms=mp||[];S.areaPerms=S.areas.map(x=>x.id);S.modulePerms=S.modules.map(x=>x.id);
  }else{
    const [ap,mp]=await Promise.all([must(db.from('user_area_permissions').select('*').eq('user_id',S.profile.id)),must(db.from('user_module_permissions').select('*').eq('user_id',S.profile.id))]);
    S.areaPerms=(ap||[]).map(x=>x.area_id);S.modulePerms=(mp||[]).map(x=>x.module_id);S.profiles=[S.profile];
  }
  setSync('Conectado');
}
