function moldControlModule(){return S.modules.find(m=>m.code==='molds-control'||m.is_mold_control)}
function permittedAreas(){return S.areas.filter(a=>active(a)&&(isManager()||S.areaPerms.includes(a.id)))}
function permittedModules(){return S.modules.filter(m=>active(m)&&!m.is_mold_control&&(isManager()||S.modulePerms.includes(m.id)))}
function machinesForModule(id){return S.machines.filter(m=>m.module_id===id&&active(m)).sort((a,b)=>a.sort_order-b.sort_order||a.name.localeCompare(b.name,'es'))}
function itemsForModule(id){return S.items.filter(x=>x.module_id===id&&active(x)).sort((a,b)=>a.sort_order-b.sort_order||a.label.localeCompare(b.label,'es'))}
function paramsForMold(id){return S.moldParams.filter(x=>x.mold_id===id&&active(x)).sort((a,b)=>a.sort_order-b.sort_order)}
function machineModule(machineId){const ma=byId(S.machines,machineId);return ma?byId(S.modules,ma.module_id):null}
function machineArea(machineId){const mo=machineModule(machineId);return mo?byId(S.areas,mo.area_id):null}
function canMolds(){const mm=moldControlModule();return isManager()||!!(mm&&S.modulePerms.includes(mm.id))}

