async function loadDashboard(){
  if(!isManager())return;
  try{
    setSync('Actualizando dashboard…');const date=$('workDate').value||today();
    const reviews=await must(db.from('review_sessions').select('*').eq('work_date',date).order('started_at'));
    const ids=(reviews||[]).map(r=>r.id);let answers=[],random=[];
    if(ids.length)answers=await must(db.from('review_answers').select('*').in('review_id',ids));
    random=await must(db.from('random_photo_assignments').select('*').eq('work_date',date));
    S.dashboard={reviews:reviews||[],answers:answers||[],random:random||[]};renderDashboard();await renderEvidenceDashboard();setSync('Conectado');
  }catch(e){fail(e,'Dashboard');setSync('Error de sincronización')}
}
function dashboardFiltered(){
  const D=S.dashboard||{reviews:[],answers:[],random:[]},area=$('dashboardArea').value||'all',resp=$('dashboardResponsible').value||'all';
  const reviews=D.reviews.filter(r=>{const a=machineArea(r.machine_id)?.id;return (area==='all'||a===area)&&(resp==='all'||r.reviewed_by===resp)});const ids=new Set(reviews.map(r=>r.id));
  const answers=D.answers.filter(a=>ids.has(a.review_id));const random=D.random.filter(x=>{const ma=machineArea(x.machine_id)?.id;return(area==='all'||ma===area)&&(resp==='all'||x.responsible_id===resp)});return{reviews,answers,random};
}
function populateDashboardFilters(){
  const oldA=$('dashboardArea').value||'all',oldR=$('dashboardResponsible').value||'all';$('dashboardArea').innerHTML='<option value="all">Todas</option>'+S.areas.filter(active).map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('');$('dashboardArea').value=[...$('dashboardArea').options].some(o=>o.value===oldA)?oldA:'all';
  $('dashboardResponsible').innerHTML='<option value="all">Todos</option>'+S.profiles.filter(p=>p.role==='responsable'&&p.active).map(p=>`<option value="${p.id}">${esc(p.full_name)}</option>`).join('');$('dashboardResponsible').value=[...$('dashboardResponsible').options].some(o=>o.value===oldR)?oldR:'all';
}
function renderDashboard(){
  if(!S.dashboard)return;populateDashboardFilters();const {reviews,answers,random}=dashboardFiltered();const area=$('dashboardArea').value||'all';
  const operationalMachines=S.machines.filter(m=>active(m)&&!machineModule(m.id)?.is_mold_control&&(area==='all'||machineArea(m.id)?.id===area));
  const checklist=reviews.filter(r=>r.kind==='checklist'),mold=reviews.filter(r=>r.kind==='mold');const closed=reviews.filter(r=>r.status==='closed').length,failures=answers.filter(a=>a.status==='no').length,openObs=answers.filter(a=>a.observation&&!a.observation_closed).length;
  const uniqueClosed=new Set(checklist.filter(r=>r.status==='closed').map(r=>`${r.machine_id}|${r.shift}`)).size,expected=operationalMachines.length*3,pending=Math.max(0,expected-uniqueClosed);const randomDone=random.filter(x=>x.fulfilled).length;
  $('dashboardKpis').innerHTML=`<div class="kpi ok"><b>${closed}</b><span>Rondas cerradas</span></div><div class="kpi warn"><b>${pending}</b><span>Pendientes de checklist</span></div><div class="kpi bad"><b>${failures}</b><span>Fallas</span></div><div class="kpi warn"><b>${openObs}</b><span>Observaciones abiertas</span></div><div class="kpi"><b>${randomDone}/${random.length}</b><span>Fotos aleatorias cumplidas</span></div>`;
  renderResponsibleTable(reviews,answers);renderPriorities(reviews,answers,operationalMachines);renderShiftMatrix(reviews,answers,operationalMachines);renderMoldDashboard(mold,answers);
}
function userExpectedMachines(userId,areaId='all'){const mids=new Set(S.allModulePerms.filter(x=>x.user_id===userId).map(x=>x.module_id));return S.machines.filter(m=>active(m)&&mids.has(m.module_id)&&(areaId==='all'||machineArea(m.id)?.id===areaId)).length}
function renderResponsibleTable(reviews,answers){
  const areaId=$('dashboardArea').value||'all',selected=$('dashboardResponsible').value||'all';
  const rows=S.profiles.filter(p=>p.role==='responsable'&&p.active&&(selected==='all'||p.id===selected)).map(p=>{const rr=reviews.filter(r=>r.reviewed_by===p.id),ids=new Set(rr.map(r=>r.id)),aa=answers.filter(a=>ids.has(a.review_id)),expected=userExpectedMachines(p.id,areaId)*3,closed=rr.filter(r=>r.status==='closed'&&r.kind==='checklist').length,fail=aa.filter(a=>a.status==='no').length,open=aa.filter(a=>a.observation&&!a.observation_closed).length,durations=rr.filter(r=>r.duration_seconds!=null).map(r=>r.duration_seconds),avg=durations.length?Math.round(durations.reduce((a,b)=>a+b,0)/durations.length/60*10)/10:null;return{p,closed,expected,fail,open,avg}});
  $('responsibleTable').innerHTML=`<table class="data-table"><thead><tr><th>Responsable</th><th>Cerradas</th><th>Fallas</th><th>Abiertas</th><th>Duración prom.</th><th>Lectura</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.p.full_name)}</b></td><td>${r.closed}/${r.expected||'-'}</td><td><span class="badge ${r.fail?'bad':'ok'}">${r.fail}</span></td><td>${r.open}</td><td>${r.avg==null?'-':r.avg+' min'}</td><td>${r.fail||r.open?'<span class="badge bad">Corregir</span>':r.closed<r.expected?'<span class="badge warn">Pendiente</span>':'<span class="badge ok">Al día</span>'}</td></tr>`).join('')||'<tr><td colspan="6">No hay responsables.</td></tr>'}</tbody></table>`;
}
function renderPriorities(reviews,answers,machines){
  const map=new Map();for(const m of machines)map.set(m.id,{m,fail:0,open:0,closed:new Set()});for(const r of reviews){if(!map.has(r.machine_id))continue;if(r.status==='closed')map.get(r.machine_id).closed.add(r.shift)}for(const a of answers){const r=reviews.find(x=>x.id===a.review_id);if(!r||!map.has(r.machine_id))continue;if(a.status==='no')map.get(r.machine_id).fail++;if(a.observation&&!a.observation_closed)map.get(r.machine_id).open++}
  const list=[...map.values()].map(x=>({...x,pending:3-x.closed.size,score:x.fail*4+x.open*3+(3-x.closed.size)})).sort((a,b)=>b.score-a.score).slice(0,7);$('priorityList').innerHTML=list.map((x,i)=>`<div class="priority-item ${x.fail?'high':x.pending?'medium':''}"><strong>${i+1}. ${esc(x.m.name)}</strong><span>${x.fail} falla(s) · ${x.open} observación(es) · ${x.pending} turno(s) pendiente(s)</span></div>`).join('')||'<div class="notice">Sin prioridades críticas.</div>';
}
function renderShiftMatrix(reviews,answers,machines){
  const cell=(m,s)=>{const rr=reviews.filter(r=>r.kind==='checklist'&&r.machine_id===m.id&&r.shift===s).sort((a,b)=>(b.closed_at||b.started_at).localeCompare(a.closed_at||a.started_at)),r=rr[0];if(!r)return'<span class="badge warn">Pendiente</span>';const aa=answers.filter(a=>a.review_id===r.id),f=aa.filter(a=>a.status==='no').length,u=byId(S.profiles,r.reviewed_by);return`${r.status==='closed'?'<span class="badge ok">Cerrada</span>':'<span class="badge warn">En curso</span>'}<br><small>${f} falla(s) · ${esc(u?.full_name||'')}</small>`};
  $('shiftMatrix').innerHTML=`<table class="data-table"><thead><tr><th>Máquina</th><th>Turno 1</th><th>Turno 2</th><th>Turno 3</th></tr></thead><tbody>${machines.map(m=>`<tr><td><b>${esc(m.name)}</b><br><small>${esc(machineModule(m.id)?.name||'')}</small></td><td>${cell(m,1)}</td><td>${cell(m,2)}</td><td>${cell(m,3)}</td></tr>`).join('')}</tbody></table>`;
}
function renderMoldDashboard(reviews,answers){
  $('moldDashboard').innerHTML=`<table class="data-table"><thead><tr><th>Máquina</th><th>Turno</th><th>Molde</th><th>Responsable</th><th>Fallas</th><th>Estado</th></tr></thead><tbody>${reviews.map(r=>{const m=byId(S.machines,r.machine_id),mo=byId(S.molds,r.mold_id),u=byId(S.profiles,r.reviewed_by),f=answers.filter(a=>a.review_id===r.id&&a.status==='no').length;return`<tr><td>${esc(m?.name||'-')}</td><td>${r.shift}</td><td>${esc(mo?mo.code+' · '+mo.name:'-')}</td><td>${esc(u?.full_name||'-')}</td><td>${f}</td><td><span class="badge ${r.status==='closed'?'ok':'warn'}">${r.status==='closed'?'Cerrada':'En curso'}</span></td></tr>`}).join('')||'<tr><td colspan="6">Sin controles de moldes para esta fecha.</td></tr>'}</tbody></table>`;
}

